mapper.sql:
WHERE sales_orders.status > 0 AND sales_orders.balance > 0
  AND sales_orders.company_id IN (SELECT company_id FROM user_companies WHERE user_id = #{filter.userId})

    AND sales_orders.customer_id IN (SELECT customer_id FROM customer_cgroups WHERE cgroup_id= #{filter.groupId})


    AND sales_orders.customer_id = #{filter.organizationId}


    AND sales_orders.customer_contact_id = #{filter.contactId}


    AND sales_orders.branch_id = #{filter.branchId}


    AND sales_orders.total_vat > 0


    AND sales_orders.total_vat < 1
